import{z as h,x as p,o as r,c,q as s,j as n,D as t,d,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"线程化分派","description":"","frontmatter":{"title":"线程化分派","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/threaded-dispatch.md","filePath":"cs/threaded-dispatch.md","lastUpdated":1791413859000}'),E={name:"cs/threaded-dispatch.md"};function A(B,a,m,u,g,f){const l=p("Mermaid");return r(),c("div",null,[a[2]||(a[2]=s('<h1 id="线程化分派" tabindex="-1">线程化分派 <a class="header-anchor" href="#线程化分派" aria-label="Permalink to &quot;线程化分派&quot;">​</a></h1><div class="epigraph"><p>把下一条字节码的处理地址直接写进流：间接跳转到该地址，而不是每次回到中央 `switch`。减少分派的间接预测失败。</p><footer>—— 据 Ertl and Gregg, The Structure and Performance of Efficient Interpreters；Bell, Threaded Code, 1973 整理</footer></div><p>上一课<a href="/cs/stack-vs-register-vm">栈式对寄存器式</a> 选了编码。缺口是<strong>分派</strong>：<code>switch</code> 每个 case 后跳回循环头，分支预测惨。线程化：computed goto（GCC 标签作值），每条 handler 末尾 <code>goto *pc++</code>。本课钉 indirect threading / direct / context threading，不写 JIT。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>解释器热路径是分派，不是加法本身。线程化把「取下一条入口」变成间接跳。缺口是<strong>控制流形状</strong>，不是操作数编码。</p><p>直接线程：指令流就是地址数组。间接：操作码仍是字节，经表变地址。Token threaded：折中。</p><h3 id="线程化不是操作系统线程" tabindex="-1">线程化不是操作系统线程 <a class="header-anchor" href="#线程化不是操作系统线程" aria-label="Permalink to &quot;线程化不是操作系统线程&quot;">​</a></h3><p>名字来自「用地址串起来」。与 pthread 无关。不要混。</p><p><span class="marginnote">Bell 1973。Ertl–Gregg。Forth 传统。C 的 <code>goto *</code> 是 GNU 扩展，可移植要用跳表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现：<code>void* table[256]</code>；handler 末 <code>goto *table[*pc++]</code>。超级指令：把高频对（load+add）合成一 handler，减分派次数——与<a href="/cs/inlining-heuristics">内联</a> 同思想在解释器里。</p>',11)),(r(),n(i,null,{default:t(()=>[o(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22%E6%93%8D%E4%BD%9C%E7%A0%81%22%5D%20--%3E%20TBL%5B%22%E5%85%A5%E5%8F%A3%E8%A1%A8%22%5D%0A%20%20TBL%20--%3E%20H%5B%22handler%22%5D%0A%20%20H%20--%3E%20NEXT%5B%22%E9%97%B4%E6%8E%A5%E8%B7%B3%E4%B8%8B%E4%B8%80%E6%9D%A1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 PGO：按轮廓选超级指令。与 JIT：热点仍编译，冷路径留线程化解释。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[d("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"间接跳仍难预测，但比「都跳回同一 switch」好。代码体积：handler 复制。调试：PC 仍要可映射源。",-1)),a[6]||(a[6]=e("p",null,"两种控制流形状的差别：",-1)),(r(),n(i,null,{default:t(()=>[o(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20SW%5B%22%E4%B8%AD%E5%A4%AE%20switch%22%5D%0A%20%20%20%20A1%5B%22%E5%8F%96%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20S1%5B%22%E8%B7%B3%E5%9B%9E%20switch%20%E5%88%A4%E6%96%AD%22%5D%0A%20%20%20%20S1%20--%3E%20H1%5B%22%E6%89%A7%E8%A1%8C%20handler%22%5D%0A%20%20%20%20H1%20--%3E%20S1%0A%20%20end%0A%20%20subgraph%20TH%5B%22%E7%BA%BF%E7%A8%8B%E5%8C%96%E5%88%86%E6%B4%BE%22%5D%0A%20%20%20%20A2%5B%22%E5%8F%96%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20H2%5B%22%E6%89%A7%E8%A1%8C%20handler%22%5D%0A%20%20%20%20H2%20--%3E%20A2%0A%20%20end%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[d(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">直觉类比：中央 switch 像所有快递都要回总仓分拣一次再发出；线程化像每件包裹分拣完就写着下一站地址直发。省下的正是每条指令一次的「绕回路口」——它是最频繁的控制流，预测失败的代价也乘上了这条频率。</span></p><p>不要在 handler 里调用会改变栈对齐的未知函数而不保存 VM 状态。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写方法 JIT。后课默认：高效解释器用线程化分派。下一课方法 JIT 与热点。</p><p><span class="marginnote">术语翻译：「线程化分派」里的线程不是操作系统线程——是说指令流像用「下一跳地址」一根线串起来：每条 handler 干完活直接跳去下一条，不再绕回中央路口。名字来自 Bell 1973 的 threaded code。</span></p><p><span class="marginnote">为什么重要：分支预测器对两种形状的待遇不同。switch 里每个 case 都回到同一个地址，预测器难猜该出哪个方向；handler 末尾的间接跳目标虽各不相同，但与操作码强相关，训练之后命中率明显更高——这就是同一解释器换个分派方式就能快百分之几十的原因。</span></p><p>也不把线程化当 GPU warp。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>线程化：handler 末间接跳，去掉中央 switch。</li><li>超级指令减分派。</li><li>仍是解释器，不是 native 编译。</li><li>出处：Bell, 1973；Ertl and Gregg。</li></ul>',9))])}const _=h(E,[["render",A]]);export{D as __pageData,_ as default};
